/** 4.svg's glossy 3D pushpin — kept out of `PIN_GLYPHS` because its fills are
 *  gradients rather than flat colours, same reason `TIP_GLYPHS.circle` gets
 *  its own defs component instead of a plain `fill` string. */
const PUSHPIN_GLYPHS: { d: string; opacity?: number }[] = [
  { d: "M219.855 232.637L248.703 505.434C249.629 514.189 262.371 514.189 263.297 505.434L292.145 232.637H219.855Z" },
  { d: "M292.145 232.637H219.854L222.767 260.177C259.172 256.321 290.823 245.137 290.823 245.137L292.145 232.637Z" },
  { d: "M256 250.056C325.051 250.056 381.028 194.079 381.028 125.028C381.028 55.9769 325.051 0 256 0C186.949 0 130.972 55.9769 130.972 125.028C130.972 194.079 186.949 250.056 256 250.056Z" },
  { d: "M256 250.056C325.051 250.056 381.028 194.079 381.028 125.028C381.028 55.9769 325.051 0 256 0C186.949 0 130.972 55.9769 130.972 125.028C130.972 194.079 186.949 250.056 256 250.056Z", opacity: 0.5 },
];

/** Pushpin's gradient stops, copied from 4.svg's `<defs>`. */
function PushpinDefs({ ids }: { ids: string[] }) {
  return (
    <defs>
      <linearGradient id={ids[0]} x1="212.562" y1="372.319" x2="256.62" y2="372.319" gradientUnits="userSpaceOnUse">
        <stop stopColor="#A996EB" />
        <stop offset="1" stopColor="#D7D1EB" />
      </linearGradient>
      <linearGradient id={ids[1]} x1="263.927" y1="227.163" x2="230.973" y2="272.151" gradientUnits="userSpaceOnUse">
        <stop stopColor="#7662BD" />
        <stop offset="1" stopColor="#7662BD" stopOpacity="0" />
      </linearGradient>
      <radialGradient id={ids[2]} cx="0" cy="0" r="1" gradientUnits="userSpaceOnUse" gradientTransform="translate(258.197 91.638) scale(125.028 125.028)">
        <stop stopColor="#FF4757" />
        <stop offset="1" stopColor="#AB2C37" />
      </radialGradient>
      <radialGradient id={ids[3]} cx="0" cy="0" r="1" gradientUnits="userSpaceOnUse" gradientTransform="translate(298.176 59.42) scale(125.028 125.028)">
        <stop stopColor="#fff" />
        <stop offset="1" stopColor="#fff" stopOpacity="0" />
      </radialGradient>
    </defs>
  );
}

/** Same bg/mask/fg reconstruction as `OFFER_LAYOUT` — see that constant's
 *  comment for why a source file's own background sometimes has to be
 *  rebuilt as a real mask instead of painted verbatim. Only `classic` needs
 *  it; `marker` and `landed` are `fg`-only. */
const PIN_LAYOUT: Record<string, { bg?: number[]; mask?: number[]; fg: number[] }> = {
  classic: { bg: [0], mask: [1, 3], fg: [2, 4] },
  marker: { fg: [0, 1, 2] },
  landed: { fg: [0, 1, 2, 3, 4, 5] },
};

/** The frame's own fixed artwork, rendered exactly as authored — no accent
 *  tint, the same fixed-palette exception as every other rebuilt sticker. */
function PinFrame({ variant }: { variant: string }) {
  const reactId = useId();
  const maskId = useId();
  if (variant === "pushpin") {
    const ids = [0, 1, 2, 3].map((i) => `${reactId}-${i}`);
    return (
      <>
        <PushpinDefs ids={ids} />
        {PUSHPIN_GLYPHS.map((p, i) => (
          <path key={i} d={p.d} fill={`url(#${ids[i]})`} opacity={p.opacity} />
        ))}
      </>
    );
  }
  const paths = PIN_GLYPHS[variant] ?? PIN_GLYPHS.classic;
  const layout = PIN_LAYOUT[variant] ?? PIN_LAYOUT.classic;
  return (
    <>
      {layout.bg && layout.mask && layout.mask.length > 0 && (
        <>
          <mask id={maskId} maskUnits="userSpaceOnUse" x="0" y="0" width="512" height="512">
            <rect x="0" y="0" width="512" height="512" fill="white" />
            {layout.mask.map((idx) => (
              <path key={idx} d={paths[idx].d} fill="black" />
            ))}
          </mask>
          <g mask={`url(#${maskId})`}>
            {layout.bg.map((idx) => (
              <path key={idx} d={paths[idx].d} fill={paths[idx].fill} />
            ))}
          </g>
        </>
      )}
      {layout.fg.map((idx) => (
        <path key={idx} d={paths[idx].d} fill={paths[idx].fill} />
      ))}
    </>
  );
}

/** Map pin for Find Us. Bobs after it lands. Every variant is real artwork
 *  from the user's own source files — no internal text, so (unlike the
 *  discount badge or tip numeral) there's nothing dynamic to overlay. */
export function MapPin({ values, frame, variant = "classic", overrides }: LayerRenderProps) {
  const interpolate = createInterpolate(values.animationStyle as string | undefined);
  const bob = frame > 28 ? interpolate(frame % 60, [0, 10, 20], [0, -10, 0]) : 0;
  const boxScale = (overrides?.sizePct ?? 100) / 100;
  const boxSize = 200 * boxScale;

  return (
    <div style={{ transform: `translateY(${bob}px)`, width: `${boxSize}px`, height: `${boxSize}px` }}>
      <svg viewBox="0 0 512 512" width="100%" height="100%" style={{ filter: "drop-shadow(0 8px 16px rgba(0,0,0,0.35))", overflow: "visible" }}>
        <PinFrame variant={variant} />
      </svg>
    </div>
  );
}

