/** Circle's gradient stops, copied from 1.svg's `<defs>`. */
function TipCircleDefs({ shineId, fillId }: { shineId: string; fillId: string }) {
  return (
    <defs>
      <linearGradient id={fillId} x1="6" y1="256" x2="506" y2="256" gradientUnits="userSpaceOnUse">
        <stop stopColor="#2BC4F3" />
        <stop offset="0.5" stopColor="#00AEEE" />
        <stop offset="1" stopColor="#0095DA" />
      </linearGradient>
      <linearGradient id={shineId} x1="176.86" y1="158.376" x2="442.01" y2="423.526" gradientUnits="userSpaceOnUse">
        <stop stopColor="#000" stopOpacity="0.49" />
        <stop offset="1" stopColor="#000" stopOpacity="0" />
      </linearGradient>
    </defs>
  );
}

/** The frame's own fixed artwork, rendered exactly as authored — no accent
 *  tint, the same fixed-palette exception as every other rebuilt sticker. */
function TipFrame({ variant }: { variant: string }) {
  const paths = TIP_GLYPHS[variant] ?? TIP_GLYPHS.circle;
  const fillId = useId();
  const shineId = useId();
  return (
    <>
      {variant === "circle" && <TipCircleDefs fillId={fillId} shineId={shineId} />}
      {paths.map((p, i) => (
        <path
          key={i}
          d={p.d}
          fill={variant === "circle" ? (i === 0 ? `url(#${fillId})` : `url(#${shineId})`) : p.fill}
        />
      ))}
    </>
  );
}

/** How much inner padding each frame needs before its digit stops reading as
 *  cramped against the edge, and how much to shrink the digit's own type. */
const TIP_INSET: Record<string, string> = {
  // These insets must leave room for the dynamic digit inside the 220px
  // sticker. The former 150px coin inset consumed more than the entire box
  // (300px across both sides), which made the number overflow outside the
  // yellow coin whenever its size was changed.
  circle: "32px",
  coin: "44px",
  ribbon: "42px 45px 65px",
  squircle: "48px",
};

const TIP_TEXT_SCALE: Record<string, number> = {
  circle: 1,
  coin: 0.62,
  ribbon: 0.85,
  squircle: 0.9,
};

/** The tip number, in the corner — carrying a tip's identity without a
 *  caption chip. Every variant is real SVG artwork from the user's own
 *  source files, with the file's own baked digit dropped in favour of the
 *  app's dynamic number. */
export function TipNumeral({ values, variant = "circle", overrides }: LayerRenderProps) {
  const tipNumber = Number(values.tipNumber ?? 1);
  // Same reasoning as the discount badge: this box is a fixed size regardless
  // of its content, so Size needs to scale the box itself, not just the digit
  // inside it.
  const boxScale = (overrides?.sizePct ?? 100) / 100;
  const boxSize = 220 * boxScale;

  const digitColor = variant === "coin" ? "#231F20" : "#fff";

  return (
    <div style={{ position: "relative", width: `${boxSize}px`, height: `${boxSize}px` }}>
      <svg viewBox="0 0 512 512" width="100%" height="100%" style={{ position: "absolute", inset: 0, filter: "drop-shadow(0 8px 20px rgba(0,0,0,0.35))" }}>
        <TipFrame variant={variant} />
      </svg>
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: scaledInset(TIP_INSET[variant] ?? "0px", boxScale),
          boxSizing: "border-box",
        }}
      >
        <div
          style={applyTextOverrides(
            { fontSize: `${170 * (TIP_TEXT_SCALE[variant] ?? 1)}px`, fontWeight: 900, color: digitColor, lineHeight: 1, textShadow: "0 2px 8px rgba(0,0,0,0.35)" },
            overrides,
          )}
        >
          {tipNumber}
        </div>
      </div>
    </div>
  );
}

/**
 * Confetti for Grand Opening. Ambient, not a layer: it covers the whole canvas
 * and there is nothing meaningful to select or drag, so it stays out of the
 * layer list.
 */
export function Confetti({ values, accent, frame }: LayerRenderProps) {
  const interpolate = createInterpolate(values.animationStyle as string | undefined);
  const pieces = Array.from({ length: 20 }, (_, i) => ({
    x: 5 + i * 4.75,
    delay: i * 2,
    color: [accent, "#FFD700", "#FF6B6B", "#4ECDC4", "#fff"][i % 5],
    size: 14 + (i % 5) * 7,
  }));

  return (
    <>
      {pieces.map((c, i) => {
        const y = interpolate(frame, [c.delay, c.delay + 55], [-5, 108]);
        const opacity = interpolate(frame, [c.delay, c.delay + 15], [0, 0.9]);
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              pointerEvents: "none",
              left: `${c.x}%`,
              top: `${y}%`,
              opacity,
              width: `${c.size}px`,
              height: `${c.size}px`,
              background: c.color,
              borderRadius: i % 3 === 0 ? "50%" : "2px",
              transform: `rotate(${frame * (i % 2 === 0 ? 4 : -3)}deg)`,
            }}
          />
        );
      })}
    </>
  );
}

/**
 * Every built-in sticker, keyed by a stable string id rather than the
 * component reference itself — a duplicated sticker becomes a plain
 * `ExtraLayer` (see `newExtraId`/schema.ts) that must stay JSON-serialisable
 * like every other extra, so it stores this key and looks the component back
 * up here at render time instead of carrying a function around in state.
 *
 * `valuesKey` names the one field a sticker reads out of the post's
 * `values` (e.g. `rating`, `discount`) — a duplicate snapshots that into its
 * own `value` so the copy is independent, the same way duplicated text gets
 * its own copy of the string instead of staying bound to the original.
 */
export const STICKER_REGISTRY: Record<
  string,
  {
    render: FC<LayerRenderProps>;
    variants: VariantOption[];
    defaultVariant: string;
    hasInternalText?: boolean;
    valuesKey?: string;
    valueField?: Omit<NumberField, "key" | "type">;
    /** Matches the same component's `LayerDef.previewScale`, so a duplicated
     *  sticker's variant swatches are sized the same as the original's. */
    previewScale?: number;
  }
> = {
  rating: {
    render: RatingRow,
    variants: RATING_VARIANTS,
    defaultVariant: "classic",
    valuesKey: "rating",
    valueField: { label: "Stars", default: 5, min: 1, max: 5 },
    // The star's own artwork is full-bleed (fills ~100% of its 512 viewBox,
    // confirmed by rasterizing and scanning for its painted pixel bounds —
    // same as the discount badge's own artwork below), but its swatch-mode
    // svg renders at a 100px CSS base, a very different intrinsic size from
    // a badge's 440px box. Picking each sticker's own scale so both land on
    // the same *visible* pixel width in the 56px swatch (~46px, based on
    // that measurement) is what actually makes "compare the two" hold up —
    // matching scale numbers across different intrinsic sizes doesn't.
    previewScale: 0.46,
  },
  "discount-badge": {
    render: DiscountBadge,
    variants: BADGE_FRAME_VARIANTS,
    defaultVariant: "seal",
    hasInternalText: true,
    valuesKey: "discount",
    valueField: { label: "Discount %", default: 30, min: 5, max: 90 },
    // 440px CSS base (see `rating` above for why this scale isn't the same
    // number as a sticker with a different intrinsic base) — 0.105 lands the
    // same ~46px visible width in the swatch.
    previewScale: 0.105,
  },
  pin: {
    render: MapPin,
    variants: PIN_VARIANTS,
    defaultVariant: "classic",
    // MapPin's box is a fixed 200px CSS base now (real SVG artwork, not the
    // old ~100px CSS shapes) — 0.23 lands the same ~46px visible width in
    // the swatch as every other rebuilt sticker (see `rating` above).
    previewScale: 0.23,
  },
  "tip-numeral": {
    render: TipNumeral,
    variants: NUMBER_VARIANTS,
    defaultVariant: "circle",
    hasInternalText: true,
    valuesKey: "tipNumber",
    valueField: { label: "Number", default: 1, min: 1, max: 9 },
    // TipNumeral's box is a fixed 220px CSS base now (real SVG artwork) —
    // 0.21 lands the same ~46px visible width in the swatch as every other
    // rebuilt sticker (see `rating` above).
    previewScale: 0.21,
  },
  "grand-badge": {
    render: GrandOpeningBadge,
    variants: GRAND_BADGE_VARIANTS,
    defaultVariant: "sign",
    hasInternalText: true,
    // Same 440px CSS base as the discount badge above.
    previewScale: 0.105,
  },
};

/** Reverse lookup — which registry entry a template layer's own `render`
 *  function corresponds to, so duplicating a built-in sticker layer can
 *  store the portable string id instead of the function. */
export function stickerComponentId(render: FC<LayerRenderProps>): string | undefined {
  return Object.keys(STICKER_REGISTRY).find((key) => STICKER_REGISTRY[key].render === render);
}
